export const SITE_TITLE = "Knowledge Base";
/**
 * Shared by the `<meta name="description">`, the OG/Twitter tags and the
 * committed `public/og.png` card, so the card and the meta tags cannot drift —
 * the same arrangement `apps/tip/src/lib/site.ts` uses.
 */
export const SITE_DESCRIPTION =
  "Documentation and knowledge base for duyet.net — apps, architecture, and references.";
export const SITE_URL = "https://kb.duyet.net";

/**
 * Generated by `pnpm run og:card` (scripts/generate-og.ts) and committed, so
 * the URL referenced by `og:image` resolves on the CDN immediately after
 * deploy instead of depending on a build step succeeding.
 */
export const SITE_OG_IMAGE = `${SITE_URL}/og.png`;

/**
 * Absolute canonical URL for a KB path. Slugs and categories in this repo are
 * already URL-safe (`[a-z0-9-]`), matching what `scripts/generate-static-files.ts`
 * writes into the sitemap, so no encoding is applied here.
 */
export function siteUrl(path: string): string {
  return `${SITE_URL}${path.startsWith("/") ? path : `/${path}`}`;
}
